from typing import List

def priceCheck(products: List[str], productPrices: List[float],
               productSold: List[str], soldPrice: List[float]) -> int:
    # 价格保留两位小数，转成整数“分”再比较，避开浮点误差
    correct = {name: round(p * 100) for name, p in zip(products, productPrices)}
    return sum(1 for name, p in zip(productSold, soldPrice)
               if name in correct and round(p * 100) != correct[name])
